199: /* --------------------------------------------------------------- shared --- */
200: .screen {
201:   position: relative; min-height: 100dvh;
202:   display: flex; flex-direction: column;
203:   padding: calc(18px + var(--safe-top)) max(18px, var(--safe-right)) calc(12px + var(--safe-bottom)) max(18px, var(--safe-left));
