226: .panel {
227:   background:
228:     linear-gradient(160deg, rgba(255, 255, 255, 0.035), transparent 34%),
229:     linear-gradient(180deg, rgba(23, 20, 21, 0.97), rgba(13, 11, 12, 0.98));
