259: /* -------------------------------------------------------------- buttons --- */
260: .btn {
261:   position: relative; display: inline-flex; align-items: center; justify-content: center; gap: 9px;
262:   padding: 13px 22px; min-height: 46px;
263:   border: 1px solid var(--line); background: #1a1617; color: var(--bone);
264:   font-family: var(--display); font-size: 20px; letter-spacing: 0.09em;
265:   text-transform: uppercase; cursor: pointer; overflow: hidden;
266:   transition: transform 0.12s, background 0.18s, border-color 0.18s, box-shadow 0.18s;
267:   clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 12px 100%, 0 calc(100% - 12px));
268: }
269: .btn::after {
270:   content: ''; position: absolute; inset: 0; pointer-events: none;
271:   background: linear-gradient(120deg, transparent 30%, rgba(255, 255, 255, 0.14) 48%, transparent 62%);
272:   transform: translateX(-120%); transition: transform 0.5s ease;
273: }
274: .btn:hover::after { transform: translateX(120%); }
275: .btn:active { transform: translateY(1px) scale(0.995); }
276: .btn:disabled { opacity: 0.45; cursor: not-allowed; filter: grayscale(0.6); }
277: .btn-primary {
278:   background: linear-gradient(180deg, #c4531f, #922f12);
