287: }
288: .btn-danger:hover { background: linear-gradient(180deg, #bf2527, #7f1115); }
289: .btn-ghost { background: rgba(255, 255, 255, 0.025); }
290: .btn-ghost:hover { background: rgba(255, 255, 255, 0.07); border-color: rgba(232, 225, 210, 0.3); }
291: .btn-large { min-height: 56px; font-size: 24px; padding: 14px 30px; }
292: .btn-small { min-height: 34px; padding: 6px 13px; font-size: 15px; letter-spacing: 0.07em; }
293: .btn-block { display: flex; width: 100%; }
294: 
295: .link-btn {
296:   background: none; border: 0; padding: 2px 0; cursor: pointer;
297:   font-family: var(--type); font-size: 10px; letter-spacing: 0.16em;
