38:   --line-soft: rgba(232, 225, 210, 0.07);
39:   --bone: #e9e2d3;
40:   --bone-dim: #c7bda9;
41:   --muted: #958b80;
42:   --rust: #b3441f;
43:   --blood: #8d1318;
44:   --blood-bright: #dd2b24;
45:   --amber: #eda43c;
46:   --amber-dim: #a9742c;
47:   --acid: #9ed84d;
48:   --cyan: #69d8e6;
