83: 
84: body[data-screen='race'] { overflow: hidden; height: 100dvh; }
85: body.modal-open { overflow: hidden; }
86: body.result-open { overflow: hidden; }
87: 
88: img, svg, canvas { display: block; max-width: 100%; }
89: button, input, select, textarea { font: inherit; color: inherit; }
90: button { -webkit-tap-highlight-color: transparent; touch-action: manipulation; }
91: a { color: inherit; }
92: h1, h2, h3, h4, p { margin: 0; }
93: ::selection { background: var(--blood-bright); color: #fff; }
94: 
95: ::-webkit-scrollbar { width: 9px; height: 9px; }
96: ::-webkit-scrollbar-track { background: #0a0909; }
97: ::-webkit-scrollbar-thumb { background: #3a312c; border: 2px solid #0a0909; }
98: ::-webkit-scrollbar-thumb:hover { background: var(--rust); }
