100: /* ---------------------------------------------------------------- splash -- */
101: #boot-splash {
102:   position: fixed; inset: 0; z-index: 200;
103:   display: grid; place-content: center; justify-items: center; gap: 18px;
104:   background: radial-gradient(circle at 50% 40%, #1c1010, #050404 70%);
105:   transition: opacity 0.8s ease, visibility 0.8s;
106: }
107: #boot-splash.done { opacity: 0; visibility: hidden; }
108: .boot-skull { font-size: 54px; color: var(--blood-bright); text-shadow: 0 0 30px rgba(221, 43, 36, 0.5); animation: pulse 1.8s infinite; }
109: .boot-title { font-family: var(--display); font-size: clamp(48px, 12vw, 92px); letter-spacing: 0.14em; color: var(--bone); line-height: 0.9; }
110: .boot-bar { width: 190px; height: 3px; background: #241c1a; overflow: hidden; }
111: .boot-bar i { display: block; height: 100%; width: 40%; background: linear-gradient(90deg, var(--blood), var(--amber)); animation: bootload 1.2s ease-in-out infinite; }
112: @keyframes bootload { 0% { transform: translateX(-120%); } 100% { transform: translateX(370%); } }
113: @keyframes pulse { 50% { opacity: 0.55; } }
114: 
115: /* ---------------------------------------------------------------- layers -- */
116: #menu-bg {
117:   position: fixed; inset: 0; width: 100%; height: 100%;
118:   z-index: 0; opacity: 0.9; pointer-events: none;
119: }
120: #decor { position: fixed; inset: 0; z-index: 1; pointer-events: none; overflow: hidden; }
121: #app { position: relative; z-index: 2; min-height: 100vh; min-height: 100dvh; }
122: #race-canvas {
123:   position: fixed; inset: 0; width: 100%; height: 100%;
124:   z-index: 10; display: none; background: #09090b;
125: }
126: body[data-screen='race'] #race-canvas { display: block; }
127: #race-ui {
128:   position: fixed; inset: 0; z-index: 12; display: none;
129:   pointer-events: none; font-family: var(--body);
130: }
131: body[data-screen='race'] #race-ui { display: block; }
132: #modals { position: relative; z-index: 60; }
133: #global-toast {
134:   position: fixed; left: 50%; bottom: calc(24px + var(--safe-bottom));
135:   z-index: 150; transform: translate(-50%, 30px); opacity: 0;
136:   pointer-events: none; max-width: min(90vw, 520px);
137:   padding: 11px 20px; background: rgba(10, 9, 9, 0.94);
138:   border: 1px solid var(--line); border-left: 3px solid var(--amber);
139:   font-family: var(--display); font-size: 19px; letter-spacing: 0.08em;
140:   text-align: center; transition: 0.3s ease; box-shadow: var(--shadow);
141: }
142: #global-toast.show { opacity: 1; transform: translate(-50%, 0); }
143: #global-toast.good { border-left-color: var(--acid); color: #dcf6bf; }
144: #global-toast.bad { border-left-color: var(--blood-bright); color: #ffd0c9; }
145: 
146: /* ---------------------------------------------------------------- decor --- */
147: .decor-layer { position: absolute; inset: 0; }
148: .decor-layer::after {
149:   content: ''; position: absolute; inset: 0;
150:   background:
151:     repeating-linear-gradient(0deg, transparent 0 2px, rgba(0, 0, 0, 0.16) 2px 3px),
152:     radial-gradient(90% 80% at 50% 50%, transparent 45%, rgba(0, 0, 0, 0.65) 100%);
153:   mix-blend-mode: multiply; opacity: 0.5;
154: }
155: .chain { position: absolute; top: -40px; height: 115%; color: #4a3a30; opacity: 0.5; filter: drop-shadow(0 4px 6px rgba(0, 0, 0, 0.7)); }
156: .chain-left { left: max(-26px, calc(var(--safe-left) - 26px)); width: 66px; transform: rotate(-4deg); }
157: .chain-right { right: max(-26px, calc(var(--safe-right) - 26px)); width: 66px; transform: rotate(5deg); }
158: .chain-svg { width: 100%; height: 100%; }
159: .blood-splash {
160:   position: absolute; border-radius: 50% 44% 55% 48%;
161:   background:
162:     radial-gradient(circle at 34% 30%, rgba(126, 14, 18, 0.65), transparent 46%),
163:     radial-gradient(circle at 65% 62%, #6d0c10, #330507 74%);
164:   filter: blur(0.4px) saturate(1.2); opacity: 0.42;
165:   box-shadow: 0 0 60px rgba(70, 5, 8, 0.45);
166: }
167: .blood-1 { width: 340px; height: 300px; left: -130px; bottom: -80px; transform: rotate(12deg); }
168: .blood-2 { width: 240px; height: 300px; right: -90px; top: 22%; transform: rotate(-15deg); opacity: 0.3; }
169: .blood-3 { width: 130px; height: 90px; right: 10%; bottom: 6%; transform: rotate(22deg); opacity: 0.28; }
170: .bone-pile { position: absolute; left: 2%; bottom: -8px; width: min(270px, 22vw); color: #b9a98c; opacity: 0.3; }
171: .hanging-hook { position: absolute; right: 6%; top: 0; width: 65px; color: #5d4a3c; opacity: 0.55; }
172: .ember-field { position: absolute; inset: 0; }
173: .ember-field i {
174:   position: absolute; bottom: -10px; width: 3px; height: 3px; border-radius: 50%;
175:   background: var(--amber); box-shadow: 0 0 8px var(--amber);
176:   animation: ember 9s linear infinite;
177: }
178: .ember-field i:nth-child(1) { left: 8%; animation-delay: 0s; }
179: .ember-field i:nth-child(2) { left: 18%; animation-delay: 2.2s; animation-duration: 11s; }
180: .ember-field i:nth-child(3) { left: 31%; animation-delay: 4s; }
181: .ember-field i:nth-child(4) { left: 44%; animation-delay: 1s; animation-duration: 13s; }
182: .ember-field i:nth-child(5) { left: 55%; animation-delay: 5.4s; }
183: .ember-field i:nth-child(6) { left: 66%; animation-delay: 3.1s; animation-duration: 10s; }
184: .ember-field i:nth-child(7) { left: 74%; animation-delay: 6.4s; }
185: .ember-field i:nth-child(8) { left: 83%; animation-delay: 0.7s; animation-duration: 12s; }
186: .ember-field i:nth-child(9) { left: 91%; animation-delay: 4.8s; }
187: .ember-field i:nth-child(10) { left: 97%; animation-delay: 2.8s; }
188: @keyframes ember {
189:   0% { transform: translateY(0) scale(1); opacity: 0; }
190:   12% { opacity: 1; }
191:   100% { transform: translateY(-95vh) translateX(30px) scale(0.3); opacity: 0; }
192: }
193: @media (max-width: 700px) {
194:   .chain { width: 40px; opacity: 0.3; }
195:   .bone-pile { width: 140px; opacity: 0.2; }
196:   .hanging-hook { display: none; }
