 .garage-stage canvas { position: absolute; inset: 0; width: 100%; height: 100%; z-index: 2; }
+.garage-angle-controls {
+  position: absolute; z-index: 4; top: 10px; right: 10px;
+  display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 5px;
+  max-width: calc(100% - 20px);
+}
+.garage-angle-controls button {
+  min-width: 48px; padding: 7px 9px;
+  color: var(--bone-dim); background: rgba(8, 8, 8, 0.78);
+  border: 1px solid rgba(232, 225, 210, 0.2);
+  font: 8px/1 var(--type); letter-spacing: 0.1em;
+  cursor: pointer; transition: color 0.16s, border-color 0.16s, background 0.16s;
+  backdrop-filter: blur(5px);
+}
+.garage-angle-controls button:hover,
+.garage-angle-controls button:focus-visible {
+  color: var(--amber); border-color: var(--amber-dim); background: rgba(24, 17, 12, 0.94);
+}
+.garage-angle-controls button:focus-visible { outline: 2px solid var(--amber); outline-offset: 2px; }
 .stage-glow {
   position: absolute; left: 50%; top: 52%; width: 62%; aspect-ratio: 1;
   transform: translate(-50%, -50%); border-radius: 50%;
   background: radial-gradient(circle, color-mix(in srgb, var(--c, #b3441f) 32%, transparent), transparent 65%);

